    {
      "id": "interests-ski-touring",
      "title": "Ski-touring",
      "type": "project",
      "category": "interests",
      "parentId": "interests",
      "path": "/interests/ski-touring",
      "depth": 2,
      "description": "Open spaces, fresh energy and a different perspective.",
      "layout": "",
      "projectType": "Personal interests",
      "year": "",
      "role": "",
      "tags": [],
      "tools": [],
      "connections": [],
      "order": 2,
      "featured": true,
      "thumbnail": "asset-2f5a6254c983-ski-touring.jpg",
      "images": [],
      "models": [],
      "links": [],
      "body": "\r\nI love spending time outdoors, connecting with nature, and staying active. For me, ski touring brings all these passions together. There’s something extraordinary about being high in the mountains, surrounded by snow and vast open spaces, feeling a real sense of freedom while challenging myself physically. It’s an experience that clears my mind, gives me fresh energy, and sparks the creativity and motivation I bring to everything else I do.\r\n",
      "heroVideo": null,
      "videos": []
    }
